  useEffect(() => {
    let cancelled = false;
    const loadSessions = async () => {
      if (!user?.uid) {
        setSessions([]);
        return;
      }
      setSessionsLoading(true);
      try {
        const colRef = collection(db, 'userSessions');
        const q = query(colRef, where('userId', '==', user.uid));
        const snap = await getDocs(q);
        const now = Date.now();
        const ttlMs = 1000 * 60 * 60 * 24;
        const items = snap.docs.map((d) => {
          const data: any = d.data();
          const forcedLogout = data.forcedLogout === true;
          let createdAt: Date | undefined;
          let lastSeen: Date | undefined;
          try {
            const rawCreated = data.createdAt;
            createdAt = rawCreated && typeof rawCreated.toDate === 'function' ? rawCreated.toDate() : rawCreated ? new Date(rawCreated) : undefined;
          } catch {
            createdAt = undefined;
          }
          try {
            const rawLast = data.lastSeen;
            lastSeen = rawLast && typeof rawLast.toDate === 'function' ? rawLast.toDate() : rawLast ? new Date(rawLast) : createdAt;
          } catch {
            lastSeen = createdAt;
          }
          return {
            id: d.id,
            deviceId: String(data.deviceId || ''),
            deviceName: data.deviceName ? String(data.deviceName) : undefined,
            deviceType: data.deviceType ? String(data.deviceType) : undefined,
            createdAt,
            lastSeen,
            forcedLogout
          };
        }).filter((item) => {
          if ((item as any).forcedLogout) return false;
          if (!item.lastSeen) return false;
          const t = item.lastSeen.getTime();
          if (!t || isNaN(t)) return false;
          return now - t < ttlMs;
        }).sort((a, b) => {
          const ta = a.createdAt instanceof Date ? a.createdAt.getTime() : 0;
          const tb = b.createdAt instanceof Date ? b.createdAt.getTime() : 0;
          return tb - ta;
        });
        if (!cancelled) {
          setSessions(items);
        }
      } catch {
        if (!cancelled) {
          setSessions([]);
        }
      } finally {
        if (!cancelled) {
          setSessionsLoading(false);
        }
      }
    };
    loadSessions();
    return () => {
      cancelled = true;
    };
  }, [user?.uid]);
  
